apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/assets/styles.css
+:root{
+  --bg:#0A0A0A;
+  --panel:#101010;
+  --panel2:#141414;
+  --text:#FFFFFF;
+  --muted:rgba(255,255,255,.72);
+  --muted2:rgba(255,255,255,.52);
+  --line:rgba(255,255,255,.12);
+  --accent:#2E6BFF;
+  --accent2:#FFB020;
+  --shadow:0 18px 60px rgba(0,0,0,.55);
+  --radius:18px;
+  --radius2:28px;
+}
+
+*{box-sizing:border-box}
+html{scroll-behavior:smooth}
+body{
+  margin:0;
+  font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
+  background:radial-gradient(1200px 700px at 20% 10%, rgba(46,107,255,.10), transparent 45%),
+             radial-gradient(900px 600px at 85% 20%, rgba(255,176,32,.08), transparent 45%),
+             var(--bg);
+  color:var(--text);
+  line-height:1.5;
+}
+img{max-width:100%;display:block}
+a{color:inherit;text-decoration:none}
+
+.sr-only{
+  position:absolute;
+  width:1px;height:1px;
+  padding:0;margin:-1px;
+  overflow:hidden;clip:rect(0,0,0,0);
+  white-space:nowrap;border:0;
+}
+
+.skip-link{
+  position:absolute;left:12px;top:12px;z-index:1000;
+  padding:10px 12px;border-radius:999px;
+  background:var(--panel2);border:1px solid var(--line);
+  transform:translateY(-120%);
+}
+.skip-link:focus{transform:translateY(0)}
+
+.container{width:min(1180px, calc(100% - 48px)); margin:0 auto;}
+
+.site-header{
+  position:sticky;top:0;z-index:50;
+  background:rgba(10,10,10,.72);
+  backdrop-filter:blur(14px);
+  border-bottom:1px solid rgba(255,255,255,.06);
+}
+.header-inner{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:14px 0;}
+
+.brand{display:flex;align-items:center;gap:10px;letter-spacing:.2px;}
+.brand-mark{
+  width:12px;height:12px;border-radius:999px;
+  background:linear-gradient(135deg, var(--accent), var(--accent2));
+  box-shadow:0 0 0 6px rgba(46,107,255,.12);
+}
+.brand-name{font-weight:700}
+
+.nav{display:flex;align-items:center;gap:14px;}
+.nav-toggle{
+  display:none;
+  width:44px;height:44px;
+  border-radius:12px;
+  border:1px solid var(--line);
+  background:rgba(255,255,255,.02);
+  color:var(--text);
+}
+.nav-toggle-lines{
+  display:block;width:18px;height:2px;background:var(--text);
+  margin:0 auto;position:relative;border-radius:99px;
+}
+.nav-toggle-lines::before,.nav-toggle-lines::after{
+  content:"";position:absolute;left:0;right:0;height:2px;border-radius:99px;background:var(--text);
+}
+.nav-toggle-lines::before{top:-6px}
+.nav-toggle-lines::after{top:6px}
+
+.nav-panel{display:flex;align-items:center;gap:18px;}
+.nav-link{color:var(--muted);font-weight:500;font-size:14px;letter-spacing:.2px}
+.nav-link:hover{color:var(--text)}
+.nav-link-em{color:var(--text)}
+
+.lang{position:relative}
+.lang-trigger{
+  display:flex;align-items:center;gap:8px;
+  padding:10px 12px;
+  border-radius:999px;
+  border:1px solid var(--line);
+  background:rgba(255,255,255,.02);
+  color:var(--text);
+  font-size:13px;font-weight:600;
+}
+.lang-trigger:hover{border-color:rgba(255,255,255,.22)}
+.lang-menu{
+  position:absolute;right:0;top:calc(100% + 10px);
+  width:190px;
+  padding:10px;
+  border-radius:16px;
+  background:rgba(16,16,16,.95);
+  border:1px solid rgba(255,255,255,.10);
+  box-shadow:var(--shadow);
+  display:none;
+}
+.lang.is-open .lang-menu{display:block}
+.lang-option{
+  width:100%;text-align:left;
+  padding:10px 10px;
+  border-radius:12px;
+  border:1px solid transparent;
+  background:transparent;
+  color:var(--muted);
+  font-weight:600;font-size:13px;
+}
+.lang-option:hover{background:rgba(255,255,255,.04);color:var(--text);border-color:rgba(255,255,255,.08)}
+
+.hero{padding:72px 0 54px;}
+.hero-grid{display:grid;grid-template-columns: 1.05fr .95fr;gap:42px;align-items:start;}
+.kicker{margin:0 0 14px;color:var(--muted);font-weight:600;letter-spacing:.18em;text-transform:uppercase;font-size:12px;}
+.hero-title{margin:0 0 14px;font-size: clamp(40px, 4.2vw, 64px);line-height:1.02;letter-spacing:-.02em;}
+.hero-subtitle{margin:0 0 22px;color:var(--muted);font-size:16px;max-width:60ch;}
+.hero-meta{display:flex;flex-wrap:wrap;gap:10px;}
+.pill{padding:10px 12px;border-radius:999px;border:1px solid rgba(255,255,255,.10);background:rgba(255,255,255,.02);color:var(--muted);font-weight:600;font-size:12px;}
+
+.section{padding:86px 0;}
+.section-head{margin-bottom:24px;display:flex;align-items:flex-end;justify-content:space-between;gap:16px;}
+.section-title{margin:0;font-size:32px;letter-spacing:-.01em;}
+.section-subtitle{margin:0;color:var(--muted);max-width:70ch;}
+
+.btn{
+  display:inline-flex;align-items:center;justify-content:center;gap:10px;
+  padding:12px 14px;border-radius:999px;
+  border:1px solid rgba(255,255,255,.16);
+  background:rgba(255,255,255,.02);
+  color:var(--text);
+  font-weight:700;font-size:14px;
+  transition:transform .18s ease, border-color .18s ease, background .18s ease;
+}
+.btn:hover{transform:translateY(-1px);border-color:rgba(255,255,255,.28);background:rgba(255,255,255,.04)}
+.btn:active{transform:translateY(0)}
+.btn-strong{
+  background:linear-gradient(135deg, rgba(46,107,255,.95), rgba(46,107,255,.55));
+  border-color:rgba(46,107,255,.55);
+}
+.btn-strong:hover{border-color:rgba(46,107,255,.85)}
+.btn-ghost{background:transparent}
+
+.icon-btn{
+  width:44px;height:44px;border-radius:14px;
+  border:1px solid rgba(255,255,255,.14);
+  background:rgba(255,255,255,.02);
+  color:var(--text);
+  font-weight:800;
+}
+.icon-btn:hover{border-color:rgba(255,255,255,.28)}
+
+.carousel-top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:12px;}
+.carousel-controls{display:flex;gap:10px;}
+.carousel-dots{display:flex;gap:8px;flex-wrap:wrap;}
+.dot{
+  width:9px;height:9px;border-radius:99px;border:1px solid rgba(255,255,255,.25);
+  background:transparent;cursor:pointer;padding:0;
+}
+.dot.is-active{background:linear-gradient(135deg, var(--accent), var(--accent2));border-color:transparent}
+
+.carousel-viewport{
+  overflow:hidden;
+  border-radius:var(--radius2);
+  border:1px solid rgba(255,255,255,.08);
+  background:linear-gradient(180deg, rgba(255,255,255,.02), rgba(255,255,255,.01));
+  box-shadow:var(--shadow);
+}
+.carousel-track{
+  display:flex;
+  transition:transform 500ms cubic-bezier(.2,.9,.2,1);
+  will-change:transform;
+}
+.carousel-hint{margin:10px 0 0;color:var(--muted2);font-size:12px;}
+
+.hero-card{min-width:100%;display:grid;grid-template-columns: .9fr 1.1fr;gap:0;}
+.hero-card-media{
+  min-height:340px;
+  background:
+    linear-gradient(120deg, rgba(46,107,255,.24), rgba(255,176,32,.06)),
+    url("./placeholders/hero-1.jpg");
+  background-size:cover;
+  background-position:center;
+  filter:saturate(.85) contrast(1.05);
+}
+.hero-card:nth-child(2) .hero-card-media{background-image:linear-gradient(120deg, rgba(46,107,255,.18), rgba(255,176,32,.10)), url("./placeholders/hero-2.jpg");}
+.hero-card:nth-child(3) .hero-card-media{background-image:linear-gradient(120deg, rgba(46,107,255,.16), rgba(255,176,32,.08)), url("./placeholders/hero-3.jpg");}
+.hero-card:nth-child(4) .hero-card-media{background-image:linear-gradient(120deg, rgba(46,107,255,.14), rgba(255,176,32,.12)), url("./placeholders/hero-4.jpg");}
+.hero-card:nth-child(5) .hero-card-media{background-image:linear-gradient(120deg, rgba(46,107,255,.12), rgba(255,176,32,.14)), url("./placeholders/hero-5.jpg");}
+
+.hero-card-body{padding:26px 26px 26px 26px;display:flex;flex-direction:column;justify-content:center;gap:12px;}
+.hero-tag{margin:0;color:var(--muted2);font-weight:700;font-size:12px;letter-spacing:.12em;text-transform:uppercase;}
+.hero-card-title{margin:0;font-size:24px;letter-spacing:-.01em;}
+.hero-card-text{margin:0;color:var(--muted);}
+
+.region-tabs{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0 14px;}
+.tab{
+  padding:10px 12px;border-radius:999px;
+  border:1px solid rgba(255,255,255,.14);
+  background:rgba(255,255,255,.02);
+  color:var(--muted);
+  font-weight:700;font-size:13px;
+}
+.tab:hover{border-color:rgba(255,255,255,.26);color:var(--text)}
+.tab.is-active{color:var(--text);border-color:rgba(46,107,255,.55);box-shadow:0 0 0 6px rgba(46,107,255,.10) inset;}
+
+.team-card{min-width:100%;display:grid;grid-template-columns: 1fr 1.25fr;}
+.team-photo{
+  min-height:320px;
+  background-size:cover;background-position:center;
+  filter:saturate(.85) contrast(1.05);
+}
+.team-body{padding:26px;display:flex;flex-direction:column;gap:14px;justify-content:center;}
+.team-name{margin:0;font-size:22px;letter-spacing:-.01em;}
+.team-meta{margin:0;color:var(--muted);font-weight:600}
+.team-quote{margin:0;color:var(--text);font-size:15px;line-height:1.55}
+.team-quote::before{content:"\201C";color:rgba(255,255,255,.75)}
+.team-quote::after{content:"\201D";color:rgba(255,255,255,.75)}
+
+.work-scroller{position:relative;}
+.work-track{
+  display:flex;gap:16px;
+  overflow:auto;
+  scroll-snap-type:x mandatory;
+  padding:6px 2px 18px;
+  -webkit-overflow-scrolling:touch;
+}
+.work-track::-webkit-scrollbar{height:10px}
+.work-track::-webkit-scrollbar-thumb{background:rgba(255,255,255,.10);border-radius:999px}
+.work-card{
+  scroll-snap-align:start;
+  min-width: clamp(270px, 46vw, 420px);
+  border-radius:var(--radius2);
+  overflow:hidden;
+  border:1px solid rgba(255,255,255,.08);
+  background:rgba(255,255,255,.02);
+  box-shadow:var(--shadow);
+}
+.work-thumb{height:210px;background-size:cover;background-position:center;filter:saturate(.85) contrast(1.05);
+  background-image:linear-gradient(120deg, rgba(46,107,255,.18), rgba(0,0,0,.4)), url("./placeholders/work-1.jpg");
+}
+.work-card:nth-child(2) .work-thumb{background-image:linear-gradient(120deg, rgba(255,176,32,.16), rgba(0,0,0,.42)), url("./placeholders/work-2.jpg");}
+.work-card:nth-child(3) .work-thumb{background-image:linear-gradient(120deg, rgba(46,107,255,.12), rgba(0,0,0,.46)), url("./placeholders/work-3.jpg");}
+.work-card:nth-child(4) .work-thumb{background-image:linear-gradient(120deg, rgba(255,176,32,.10), rgba(0,0,0,.50)), url("./placeholders/work-4.jpg");}
+.work-card:nth-child(5) .work-thumb{background-image:linear-gradient(120deg, rgba(46,107,255,.10), rgba(0,0,0,.48)), url("./placeholders/work-5.jpg");}
+.work-card:nth-child(6) .work-thumb{background-image:linear-gradient(120deg, rgba(255,176,32,.12), rgba(0,0,0,.46)), url("./placeholders/work-6.jpg");}
+.work-body{padding:16px 16px 18px;}
+.work-client{margin:0;color:var(--muted2);font-weight:800;font-size:12px;letter-spacing:.12em;text-transform:uppercase;}
+.work-title{margin:8px 0 10px;font-size:18px;letter-spacing:-.01em;}
+.work-quote{margin:0;color:var(--muted);font-size:14px;}
+.work-attrib{margin:10px 0 0;color:var(--muted2);font-weight:600;font-size:12px;}
+.work-controls{display:flex;gap:10px;justify-content:flex-end;}
+
+.cta{padding:52px 0;background:linear-gradient(135deg, rgba(46,107,255,.18), rgba(255,176,32,.08));border-top:1px solid rgba(255,255,255,.08);border-bottom:1px solid rgba(255,255,255,.08)}
+.cta-inner{display:flex;align-items:center;justify-content:space-between;gap:20px;}
+.cta-title{margin:0 0 8px;font-size:30px;letter-spacing:-.01em}
+.cta-text{margin:0;color:var(--muted);max-width:72ch}
+
+.split{display:grid;grid-template-columns:1.1fr .9fr;gap:32px;align-items:start;}
+.capabilities{display:grid;gap:12px;}
+.capability{padding:18px;border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.08);
+  background:rgba(255,255,255,.02);
+}
+.capability h3{margin:0 0 6px;font-size:16px}
+.capability p{margin:0;color:var(--muted)}
+
+.insights-grid{display:grid;grid-template-columns:repeat(4, 1fr);gap:14px;}
+.insight-card{
+  padding:14px;border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.08);
+  background:rgba(255,255,255,.02);
+  transition:transform .2s ease, border-color .2s ease;
+}
+.insight-card:hover{transform:translateY(-2px);border-color:rgba(255,255,255,.18)}
+.insight-thumb{height:120px;border-radius:14px;margin-bottom:12px;
+  background-size:cover;background-position:center;
+  background-image:linear-gradient(120deg, rgba(46,107,255,.14), rgba(0,0,0,.55)), url("./placeholders/insight-1.jpg");
+}
+.insight-card:nth-child(2) .insight-thumb{background-image:linear-gradient(120deg, rgba(255,176,32,.12), rgba(0,0,0,.55)), url("./placeholders/insight-2.jpg");}
+.insight-card:nth-child(3) .insight-thumb{background-image:linear-gradient(120deg, rgba(46,107,255,.10), rgba(0,0,0,.58)), url("./placeholders/insight-3.jpg");}
+.insight-card:nth-child(4) .insight-thumb{background-image:linear-gradient(120deg, rgba(255,176,32,.10), rgba(0,0,0,.58)), url("./placeholders/insight-4.jpg");}
+.insight-card:nth-child(5) .insight-thumb{background-image:linear-gradient(120deg, rgba(46,107,255,.10), rgba(0,0,0,.58)), url("./placeholders/insight-5.jpg");}
+.insight-card:nth-child(6) .insight-thumb{background-image:linear-gradient(120deg, rgba(255,176,32,.10), rgba(0,0,0,.58)), url("./placeholders/insight-6.jpg");}
+.insight-card:nth-child(7) .insight-thumb{background-image:linear-gradient(120deg, rgba(46,107,255,.10), rgba(0,0,0,.58)), url("./placeholders/insight-7.jpg");}
+.insight-card:nth-child(8) .insight-thumb{background-image:linear-gradient(120deg, rgba(255,176,32,.10), rgba(0,0,0,.58)), url("./placeholders/insight-8.jpg");}
+.insight-type{margin:0;color:var(--muted2);font-weight:800;font-size:12px;letter-spacing:.12em;text-transform:uppercase}
+.insight-title{margin:8px 0 10px;font-size:15px;letter-spacing:-.01em}
+.link{color:rgba(255,255,255,.86);font-weight:800;font-size:13px}
+.link:hover{color:var(--text);text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:3px}
+
+.principles{display:grid;grid-template-columns:repeat(2, 1fr);gap:14px;}
+.principle{padding:18px;border-radius:var(--radius2);border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.02)}
+.principle h3{margin:0 0 8px;font-size:18px;letter-spacing:-.01em}
+.principle p{margin:0;color:var(--muted)}
+
+.footer{padding:70px 0 44px;border-top:1px solid rgba(255,255,255,.08);background:rgba(0,0,0,.35)}
+.footer-top{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-bottom:24px;}
+.footer-cta{padding:20px;border-radius:var(--radius2);border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.02)}
+.footer-cta h2{margin:0 0 6px;font-size:20px}
+.footer-cta p{margin:0 0 14px;color:var(--muted)}
+.footer-links{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
+.footer-title{margin:0 0 10px;font-size:14px;letter-spacing:.12em;text-transform:uppercase;color:rgba(255,255,255,.82)}
+.footer-links a{display:block;color:var(--muted);padding:6px 0}
+.footer-links a:hover{color:var(--text)}
+.muted{color:var(--muted2);margin:0}
+
+.cookie{
+  position:fixed;left:16px;right:16px;bottom:16px;z-index:90;
+}
+.cookie-inner{
+  margin:0 auto;
+  width:min(980px, 100%);
+  border-radius:var(--radius2);
+  border:1px solid rgba(255,255,255,.10);
+  background:rgba(16,16,16,.92);
+  box-shadow:var(--shadow);
+  padding:16px;
+  display:flex;align-items:flex-start;justify-content:space-between;gap:14px;
+}
+.cookie-title{margin:0 0 6px;font-weight:900;letter-spacing:-.01em}
+.cookie-text{margin:0;color:var(--muted)}
+.cookie-actions{display:flex;gap:10px;flex-wrap:wrap;justify-content:flex-end}
+
+.modal{position:fixed;inset:0;z-index:95;display:grid;place-items:center;padding:18px}
+.modal-backdrop{position:absolute;inset:0;background:rgba(0,0,0,.62)}
+.modal-card{position:relative;width:min(720px, 100%);border-radius:var(--radius2);
+  border:1px solid rgba(255,255,255,.10);
+  background:rgba(16,16,16,.96);
+  box-shadow:var(--shadow);
+  padding:16px;
+}
+.modal-head{display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid rgba(255,255,255,.08);padding-bottom:10px;margin-bottom:12px}
+.modal-head h2{margin:0;font-size:18px}
+.modal-body{display:grid;gap:12px}
+.toggles{display:grid;gap:10px}
+.toggle-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px;border-radius:16px;border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.02)}
+.toggle-title{margin:0;font-weight:900}
+.chip{padding:8px 10px;border-radius:999px;border:1px solid rgba(255,255,255,.14);color:rgba(255,255,255,.82);font-weight:800;font-size:12px}
+.switch{width:46px;height:26px;appearance:none;border-radius:999px;position:relative;outline:none;cursor:pointer;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.14)}
+.switch:checked{background:rgba(46,107,255,.35);border-color:rgba(46,107,255,.55)}
+.switch::after{content:"";position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:99px;background:rgba(255,255,255,.88);transition:transform .18s ease}
+.switch:checked::after{transform:translateX(20px)}
+.modal-actions{display:flex;justify-content:flex-end;border-top:1px solid rgba(255,255,255,.08);padding-top:12px;margin-top:12px}
+
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns:1fr;gap:26px}
+  .hero{padding-top:54px}
+}
+
+@media (max-width: 820px){
+  .section-head{flex-direction:column;align-items:flex-start}
+  .insights-grid{grid-template-columns:repeat(2, 1fr)}
+  .principles{grid-template-columns:1fr}
+  .footer-top{grid-template-columns:1fr}
+  .footer-links{grid-template-columns:1fr}
+  .split{grid-template-columns:1fr}
+  .cta-inner{flex-direction:column;align-items:flex-start}
+  .hero-card{grid-template-columns:1fr}
+  .hero-card-media{min-height:240px}
+  .team-card{grid-template-columns:1fr}
+  .team-photo{min-height:240px}
+
+  .nav-toggle{display:inline-flex;align-items:center;justify-content:center}
+  .nav-panel{
+    position:absolute;right:24px;top:64px;
+    width:min(420px, calc(100vw - 48px));
+    flex-direction:column;align-items:flex-start;gap:12px;
+    padding:14px;
+    border-radius:18px;
+    border:1px solid rgba(255,255,255,.10);
+    background:rgba(10,10,10,.92);
+    box-shadow:var(--shadow);
+    display:none;
+  }
+  .nav.is-open .nav-panel{display:flex}
+}
+
+@media (prefers-reduced-motion: reduce){
+  html{scroll-behavior:auto}
+  .carousel-track{transition:none}
+  .btn{transition:none}
+  .insight-card{transition:none}
+}
+
*** End Patch
PATCH

